using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using UnityEngine.SceneManagement;
using LWS.TruckBowling;
using LWS.TruckBilliards;
namespace LWS.TruckSports {
public sealed partial class SportsPolishSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();string flag,folder;bool failed,finished;Keyboard keyboard;InputSettings original,probe;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){foreach(var f in new[]{"-tsPolishPerf","-tsPolishLayouts","-tsPolishVisual","-tsPolishMotion","-tsPolishBaseline","-tsPolishAI","-tsPolish"})if(Array.IndexOf(Environment.GetCommandLineArgs(),f)>=0){var g=new GameObject("Truck Sports polish validation");DontDestroyOnLoad(g);g.AddComponent<SportsPolishSmoke>().flag=f;return;}}
 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("PolishSmoke");Directory.CreateDirectory(folder);if(Application.companyName!="LWS Truck Sports Validation"&&!LWS.TruckSports.SportsProbeInputIsolation.Active){records.Add("FAIL Polish probes require an explicit private validation scope");Finish(2);return;}original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Polish software keyboard");Application.logMessageReceived+=Log;records.Add("Software devices; native pads before injection="+Gamepad.all.Count+" isolated company="+Application.companyName);steps.Push(Run());}
 void Log(string text,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){failed=true;records.Add("ERROR "+text);}}
 void Update(){if(finished)return;try{while(steps.Count>0){var step=steps.Peek();if(!step.MoveNext()){steps.Pop();continue;}if(step.Current is IEnumerator nested){steps.Push(nested);continue;}return;}Finish(failed?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("TS_POLISH_FAIL "+e);Finish(2);}}
 void Finish(int code){finished=true;File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Application.logMessageReceived-=Log;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(original!=null)InputSystem.settings=original;if(probe!=null)Destroy(probe);Time.timeScale=1;Debug.Log("TS_POLISH_FINISHED code="+code);Application.Quit(code);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> condition,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!condition()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label);yield return null;}}
 void Check(bool condition,string name){if(!condition)throw new Exception(name);records.Add("PASS "+name);Debug.Log("TS_POLISH_PASS "+name);}void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}IEnumerator Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return Delay(.15f);}
 IEnumerator Run(){yield return Delay(.5f);var front=FindAnyObjectByType<SportsFrontEnd>();Check(front!=null,"six-scene collection startup");front.Action("play");yield return Capture("00-selection");if(flag=="-tsPolishPerf"){yield return RenderPerformance();yield break;}if(flag=="-tsPolishLayouts"){yield return LayoutMatrix();yield break;}if(flag=="-tsPolishVisual"){yield return VisualChecks();yield return FixedOutcomeComparison();yield break;}if(flag=="-tsPolishMotion"){yield return BowlingCarry();yield break;}if(flag=="-tsPolishAI"){yield return BowlingGames();yield break;}yield return ArenaViews();yield return BowlingMotion(flag=="-tsPolishBaseline");yield return BilliardsOutcomes();}
 IEnumerator ArenaViews(){foreach(var sport in new[]{SportsNavigation.Billiards,SportsNavigation.Hockey,SportsNavigation.AirHockey,SportsNavigation.Wallball}){SportsNavigation.LoadSport(sport);yield return Delay(.5f);if(sport==SportsNavigation.Billiards){var s=FindAnyObjectByType<BilliardsSession>();s.SelectMode(BilliardsMode.Practice);s.StartMatch();}else if(sport==SportsNavigation.Hockey){var m=FindAnyObjectByType<LWS.TruckHockey.HockeyMatch>();foreach(var p in m.players)p.source=LWS.TruckHockey.HockeySource.AI;m.StartMatch();}else if(sport==SportsNavigation.AirHockey){var m=FindAnyObjectByType<LWS.TruckAirHockey.AirHockeyMatch>();m.Configure(LWS.TruckAirHockey.AirHockeyMode.AIVsAI);m.StartMatch();}else{var m=FindAnyObjectByType<LWS.TruckWallball.WallballMatch>();m.Configure(LWS.TruckWallball.WallballMode.AIVsAI);m.StartMatch();}yield return Delay(.25f);yield return Capture("arena-"+sport);}}
 IEnumerator EnterBowling(){SportsNavigation.LoadSport(SportsNavigation.Bowling);yield return Delay(.5f);Check(FindAnyObjectByType<BowlingMatch>()!=null,"saved Bowling entry");}
 IEnumerator BowlingMotion(bool baseline){yield return EnterBowling();var m=FindAnyObjectByType<BowlingMatch>();records.Add("Motion cases use explicit initial physical poses/velocities, not autonomous-game evidence.");foreach(var kind in new[]{"normal","sideways","backward","gutter"}){Keys();m.PresetAI(1,BowlingMode.Simultaneous);m.setup.players[0].source=BowlingSource.Keyboard;Check(m.StartMatch(),"motion fixture start "+kind);yield return Delay(.3f);var l=m.lanes[0];var t=l.truck;float x=kind=="gutter"?2.3f:0;float yaw=kind=="sideways"?90:kind=="backward"?180:0;var p=new Vector3(l.center+x,.26f,22);var q=Quaternion.Euler(0,yaw,0);t.transform.SetPositionAndRotation(p,q);t.body.position=p;t.body.rotation=q;t.body.linearVelocity=new Vector3(0,0,10);t.body.angularVelocity=kind=="normal"?Vector3.zero:new Vector3(0,.8f,0);Physics.SyncTransforms();Keys(Key.W);yield return Delay(.05f);records.Add("MOTION "+kind+" initial phase="+l.Phase+" position="+t.body.position+" velocity="+t.body.linearVelocity+" kinematic="+t.body.isKinematic+" reason="+l.Result);yield return Delay(3);records.Add("MOTION "+kind+" after3s phase="+l.Phase+" position="+t.body.position+" velocity="+t.body.linearVelocity+" kinematic="+t.body.isKinematic+" reason="+l.Result+" brake="+t.wheels[0].BrakeTorque);yield return Capture("motion-"+kind);if(!baseline)Check(t.body.position.z>25&&!t.body.isKinematic,"world momentum continues "+kind);Keys();m.ChangeSetup();}Time.timeScale=1;}
 IEnumerator BowlingGames(){yield return EnterBowling();var m=FindAnyObjectByType<BowlingMatch>();for(int game=0;game<3;game++){UnityEngine.Random.InitState(900+game);m.PresetAI(4,BowlingMode.Simultaneous);for(int i=0;i<4;i++){m.setup.players[i].difficulty=(BowlingDifficulty)Mathf.Min(i,2);m.setup.players[i].name="AI "+m.setup.players[i].difficulty+" "+game;}Check(m.StartMatch(),"seeded simultaneous game "+game);Time.timeScale=3;float start=Time.realtimeSinceStartup,next=0;int[] locks=new int[4];for(int i=0;i<4;i++)locks[i]=m.lanes[i].ScoreLocks;int gutters=0,spares=0,strikes=0,positive=0;while(!m.Finished){if(Time.realtimeSinceStartup-start>420)throw new Exception("Bowling full game timeout");for(int i=0;i<4;i++){var l=m.lanes[i];if(l.ScoreLocks<=locks[i])continue;locks[i]=l.ScoreLocks;if(l.Gutter)gutters++;if(l.Result.StartsWith("SPARE"))spares++;if(l.Result.StartsWith("STRIKE"))strikes++;if(l.LastPins>0){positive++;Check(l.LegalPinContact,"positive pinfall has physical provenance "+game+"/"+i+"/"+locks[i]);}}if(Time.realtimeSinceStartup>next){next=Time.realtimeSinceStartup+10;File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);yield return null;}yield return null;}for(int i=0;i<4;i++)records.Add("AI_GAME seed="+(900+game)+" difficulty="+m.setup.players[i].difficulty+" lane="+i+" score="+m.setup.players[i].score.ResolvedTotal+" deliveries="+m.setup.players[i].score.Deliveries);records.Add("AI_AGGREGATE seed="+(900+game)+" gutters="+gutters+" spares="+spares+" strikes="+strikes+" positive="+positive+" elapsed="+(Time.realtimeSinceStartup-start).ToString("F1")+" timescale=3; scoring/progression comparison, not real-time benchmark");yield return Capture("ai-game-"+game);Time.timeScale=1;m.ChangeSetup();}Check(!failed,"three complete seeded AI games");}
 IEnumerator BilliardsOutcomes(){SportsNavigation.LoadSport(SportsNavigation.Billiards);yield return Delay(.6f);var m=FindAnyObjectByType<BilliardsMatch>();var s=m.session;Time.timeScale=3;for(int shot=0;shot<3;shot++){s.SelectMode(BilliardsMode.Practice);Check(s.StartMatch(),"reference practice starts");yield return Wait(()=>m.AreSettled,5,"initial rack settled");Vector3 velocity=new Vector3((shot-1)*1.3f,0,13);int id=m.rules.ShotId;m.Strike(m.player,velocity);Check(m.rules.ShotId==id+1,"actual reference shot launched");yield return Wait(()=>m.AreSettled,45,"deterministic billiards shot");string text="SHOT "+shot+" turn="+m.rules.Turn+" reason="+m.rules.Notice;foreach(var b in m.balls)text+=" | "+b.number+":"+b.Pocketed+":"+b.body.position.ToString("F3");records.Add(text);yield return Capture("billiards-shot-"+shot);}Time.timeScale=1;Check(!failed,"billiards authoritative reference outcomes");}
#endif
}
}
